def find_by_ext_in_dirs(dirnames, ext):
    """Find all files in a list of directories by extension."""
    return [f for d in dirnames for f in find_by_ext(d, ext)]


def find_by_ext_in_dir(dirname, ext):
    """Find all files in a directory by extension."""
    return find_by_ext(dirname, ext)


